mapper.select:
select from homework_assignment a left join edu_class c on c.id = a.class_id left join edu_campus cp on cp.id = c.campus_id left join edu_course crs on crs.id = a.course_id left join edu_course_detail cd on cd.id = a.course_detail_id left join edu_class_schedule s on s.class_id = a.class_id and s.schedule_date = a.homework_date left join sys_user pub_u on pub_u.id = a.publish_teacher_id left join sys_user ans_u on ans_u.id = a.answer_publish_teacher_id left join sys_user close_u on close_u.id = a.close_teacher_id left join ( select assignment_id, count(1) as submitted_count from homework_submission group by assignment_id ) sub on sub.assignment_id = a.id
a.deleted = 0
and a.title like concat('%', #{title}, '%')
and a.class_id = #{classId}
and a.status = #{status}
order by a.publish_date desc, a.id desc
